mapper.update:
UPDATE user_behavior_post
SET behavior_time = #{behavior_time}
WHERE user_id = #{user_id}
  AND post_id = #{post_id}
  AND behavior_type = 1

mapper.select:
SELECT id, user_id, post_id, behavior_type, behavior_time
FROM user_behavior_post
WHERE user_id = #{user_id}
ORDER BY behavior_time DESC
LIMIT #{limit}

SELECT COUNT(*)
FROM user_behavior_post
WHERE user_id = #{user_id}

mapper.delete:
DELETE FROM user_behavior_post
WHERE user_id = #{user_id}
  AND post_id = #{post_id}
  AND behavior_type = #{behavior_type}
